format:
.app-bar-actions-title {
    margin: auto;
    text-shadow: rgb(var(--v-theme-background)) 2px 2px 1px;
}

.v-card .remove,
.v-card-text .remove,
.v-card-item {
    display: none !important;
    visibility: hidden;
    color: transparent !important;
}

.center .nrdb-switch, 
.center .v-btn-group {
    margin: auto;
}

.remove * {
    display: none !important;
    visibility: hidden;
    color: transparent !important;
}

tbody td[data-column-key=lbl] {
    font-weight: bold !important;
}

.icon-in-row {
    font-size: 1.8em;
}

.v-tab-item--selected {
    color: rgb(var(--v-theme-primary)) !important;
}

.v-main {
    padding-bottom: 2em;
}
.ui-title span {
    font-size: 1.4rem !important;
    font-weight: normal !important;
    padding: 0;
    margin-top: 0.5em;
    color: rgb(var(--v-theme-primary)) !important;
}

.ui-camera {
    text-align: center !important;
    flex: 1 0;
}
.ui-camera img {
    width: 90%;
}

.nrdb-ui-group {
    border-radius: 4px;
    box-shadow: 3px 2px 2px rgba(var(--v-theme-group-outline));
}
.v-application {
    border-top: 1px solid rgba(var(--v-theme-group-outline));
    margin-top: -1px;
}

