let describe = global.get('describe', 'memoryOnly') || {};
if (typeof describe !== 'object') {
    describe = {};
}
if (typeof describe.pages !== 'object') {
    describe.pages = {};
}

// Set default app values
describe.app = {
    'title': 'DKNR',
    'version' : '0.0',
    'git': ''
}

// Set common pages rights
