        entities[entity[e]['room']]['temperature'] = 0;
    }
    if (entity[e]['element'] === 'temperature') {
        entities[entity[e]['room']]['temperature_num']++;
        entities[entity[e]['room']]['temperature'] += Number(entity[e]['value']);
    }
    if (entities[entity[e]['room']]['temperature_num']) {
        entities[entity[e]['room']]['temperature'] = Number((entities[entity[e]['room']]['temperature'] / entities[entity[e]['room']]['temperature_num']).toFixed(1));
    }

