for (const uid in entity) {
    if (entity[uid]['room'] === room && 
        entity[uid]['hidden'] === 0
    ) {
        let group = 'unknown';
        for (const g in groups) {
            if (groups[g].includes(entity[uid]['element'])) {
                group = g;
            }
        }

        if (group !== '') {
            let value = entity[uid]['value'] || 0;
            let unit = entity[uid]['unit'];
            let name = global.get('name["entity"]["' + uid + '"]', 'memoryOnly') || '';
            let parent = global.get('name["device"]["' + entity[uid]['parent'] + '"]', 'memoryOnly') || entity[uid]['parent'];
            let icon = '';
            let color = 'empty';
            let element = entity[uid]['element'];
            let element_name = msg.dictionary.option_element[element];
            let element_icon = '';
            let source = sources[entity[uid]['source']] || ['help', entity[uid]['source']];

            // Revert value for some "rb" unit
            if (unit === 'rb') {
                value = value === 0 ? 1 : 0;
            }
            // Revert text for some elements (see describe.reverts)
            if (reverts.includes(element)) {
                value = value === 0 ? 1 : 0;
            }
            // Get icon from value
            if (typeof icons[element] !== 'undefined') {
                if (value) {
                    icon = icons[element][1];
                    color = colors.theme;
                } else {
                    icon = icons[element][0];
                    color = colors.empty;
                }
                element_icon = icons[element][1];
            }

            // Battery alert color
            if (element === 'battery' && value < 15) {
                color = colors.off;
            }

            // Get special enum value
            if (unit === 'enum') {
                let cur_enum = enums[entity[uid]['source']][entity[uid]['id']][value] || [icon, value];
                icon = cur_enum[0];
                value = cur_enum[1];
                group = 'enum';
            }

            // Format value
            if (!['8b', 'rb', 'b', 'enum', 'ts', 'time', 'text'].includes(unit) && unit !== '') {
                // Add unit text
                value = value + ' ' + unit;
            }
            else if (unit === '8b') {
                // Convert 8b in %
                value = Math.ceil(Number(value) * 100 / 255) + '%'
            }
            else if (unit === 'ts') {
                // Convert to date
                value = new Date(value).toLocaleString(msg.dictionary.common.locales);
            }
            else if (['b', 'rb'].includes(unit)) {
                // Convert to text
                if (group === 'aperture') {
                    value = value === 0 ? msg.dictionary.group_room.close : msg.dictionary.group_room.open;
                }
                else if (group === 'switch') {
                    if (element === 'shield') {
                        value = value === 0 ? msg.dictionary.group_room.inactive : msg.dictionary.group_room.active;
                    } else {
                        value = value === 0 ? msg.dictionary.group_room.off : msg.dictionary.group_room.on;
                    }
                }
            }

            // Get name from parent if none or default is set
            if (name === '' || name === entity[uid]['id']) {
                name = parent;
            }

            // Colorize unresponsive entity
            let type_icon = entity[uid]['type'] === 'sensor' ? 'leak': 'button-pointer';
            let type_color = entity[uid]['type'] === 'sensor' ? colors.empty : colors.none;
            if ((entity[uid]['seen'] + 86400000) < Date.now()) { // 24h
                type_color = colors.off;
            }

            res[group][inc[group]] = {
                'uid': uid,
